const searches = [
  { query: 'Fractional CMO United States', type: 'fractional' },
  { query: 'Part time marketing manager United States', type: 'part-time' },
  { query: 'Fractional VP of Marketing United States', type: 'fractional' },
  { query: 'Part time marketing director United States', type: 'part-time' },
  { query: 'Fractional Head of Marketing United States', type: 'fractional' },
  { query: 'Part time CMO United States', type: 'part-time' }
];

return searches.map(s => ({ json: s }));

const items = $input.all();
const allJobs = [];
const seenTitleCompany = new Set();
const seenLinks        = new Set();
const seenDescSnippets = new Set();

function isWithin24Hours(postedStr, description) {
  if (!postedStr) return false;
  const s = postedStr.toLowerCase().trim();
  const desc = (description || '').toLowerCase();
  if (desc.includes('30+ days ago') || desc.includes('weeks ago') || desc.includes('month ago') || desc.includes('30 days ago')) return false;
  if (s.includes('week') || s.includes('month') || s.includes('year') || s.includes('+')) return false;
  if (s.includes('minute') || s.includes('hour') || s.includes('just now') || s === 'today') return true;
  if (/^1\s+day/.test(s) || s === '1 day ago' || /^a day/.test(s)) return true;
  if (/\b([2-9]|[1-9]\d+)\s+day/.test(s)) return false;
  return false;
}

function isDuplicateLink(link) {
  if (!link || link.length < 10) return false;
  try {
    const base = new URL(link).origin + new URL(link).pathname;
    if (seenLinks.has(base)) return true;
    seenLinks.add(base);
  } catch(e) {
    if (seenLinks.has(link)) return true;
    seenLinks.add(link);
  }
  return false;
}

function isDuplicateDescription(desc) {
  if (!desc || desc.trim().length < 100) return false;
  const snippet = desc.substring(0, 300).toLowerCase().replace(/\s+/g, ' ').trim();
  if (seenDescSnippets.has(snippet)) return true;
  seenDescSnippets.add(snippet);
  return false;
}

for (const item of items) {

  // ── SERP API FORMAT ──────────────────────────────────────────────────────
  const serpJobs = item.json.jobs_results || [];
  for (const job of serpJobs) {
    const tcKey = `${(job.title||'').toLowerCase().trim()}|${(job.company_name||'').toLowerCase().trim()}`;
    if (seenTitleCompany.has(tcKey)) continue;
    seenTitleCompany.add(tcKey);

    const ext = job.detected_extensions || {};
    if (!isWithin24Hours(ext.posted_at, job.description)) continue;

    let bestApplyLink = job.share_link || '';
    let bestSource = job.via || '';
    if (job.apply_options && job.apply_options.length > 0) {
      const premium = job.apply_options.find(o =>
        o.title.toLowerCase().includes('linkedin') ||
        o.title.toLowerCase().includes('indeed') ||
        o.title.toLowerCase().includes('greenhouse') ||
        o.title.toLowerCase().includes('lever') ||
        o.title.toLowerCase().includes('workday') ||
        (job.company_name && o.title.toLowerCase().includes(job.company_name.toLowerCase()))
      );
      if (premium) { bestApplyLink = premium.link; bestSource = premium.title; }
      else { bestApplyLink = job.apply_options[0].link; bestSource = job.apply_options[0].title || job.via; }
    }

    if (isDuplicateLink(bestApplyLink)) continue;
    if (isDuplicateDescription(job.description)) continue;

    allJobs.push({
      title: job.title || '',
      company: job.company_name || '',
      location: job.location || 'Remote',
      description: (job.description || '').substring(0, 3000),
      job_link: job.share_link || '',
      apply_link: bestApplyLink,
      posted: ext.posted_at || '',
      schedule: ext.schedule_type || '',
      salary: ext.salary || '',
      source: bestSource,
      api_source: 'SerpAPI',
      job_id: job.job_id || `${job.title}-${job.company_name}`.replace(/\s/g,'-').toLowerCase()
    });
  }

  // ── JSEARCH API FORMAT ───────────────────────────────────────────────────
  const jsJobs = item.json.data || [];
  for (const job of jsJobs) {
    const title = job.job_title || '';
    const company = job.employer_name || '';
    const tcKey = `${title.toLowerCase().trim()}|${company.toLowerCase().trim()}`;
    if (seenTitleCompany.has(tcKey)) continue;
    seenTitleCompany.add(tcKey);

   // ── DATE GATE: explicitly block anything older than 24 hours ───────────
    let isRecent = false;
    if (job.job_posted_at_timestamp) {
      const diffHours = (Date.now() / 1000 - job.job_posted_at_timestamp) / 3600;
      isRecent = diffHours <= 24; 
    } else if (job.job_posted_at_datetime_utc) {
      const diffHours = (Date.now() - new Date(job.job_posted_at_datetime_utc).getTime()) / 3600000;
      isRecent = diffHours <= 24; 
    }
    if (!isRecent) continue;

    // ── EXPERIENCE GATE: block junior roles using JSearch's own data ────────
    const expMonths = job.job_required_experience?.required_experience_in_months;
    if (expMonths && expMonths < 48) continue;

    const applyLink = job.job_apply_link || job.job_google_link || '';
    if (isDuplicateLink(applyLink)) continue;
    if (isDuplicateDescription(job.job_description)) continue;

    const city = job.job_city || '';
    const state = job.job_state || '';
    const location = [city, state].filter(Boolean).join(', ') ||
      (job.job_is_remote ? 'Remote' : (job.job_country || 'Remote'));

    const salary = (job.job_min_salary && job.job_max_salary)
      ? `${job.job_min_salary}-${job.job_max_salary} ${job.job_salary_currency||''}`.trim() : '';

    allJobs.push({
      title, company, location,
      description: (job.job_description || '').substring(0, 3000),
      job_link: applyLink,
      apply_link: applyLink,
      posted: job.job_posted_at_datetime_utc || '',
      schedule: job.job_employment_type || '',
      salary,
      source: job.job_publisher || 'JSearch',
      api_source: 'JSearch',
      job_id: job.job_id || `${title}-${company}`.replace(/\s/g,'-').toLowerCase()
    });
  }
}

if (allJobs.length === 0) return [];
return allJobs.map(j => ({ json: j }));

const incomingJobs = $('Has Jobs?').all();
const existingData = $('Get Existing Jobs from Notion').all();

const existingTitles = new Set();
existingData.forEach(item => {
  const results = item.json.results || [];
  results.forEach(page => {
    const title = (page.properties?.['To-do']?.title?.[0]?.plain_text || '').toLowerCase().trim();
    const company = (page.properties?.['Company']?.rich_text?.[0]?.plain_text || '').toLowerCase().trim();
    if (title) existingTitles.add(`${company}|${title}`);
  });
});

function normalizeTitle(title) {
  return title
    .toLowerCase()
    .replace(/\(.*?\)/g, '')
    .replace(/[-–|,]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isSimilarTitle(a, b) {
  const na = normalizeTitle(a);
  const nb = normalizeTitle(b);
  if (na.length < 10 || nb.length < 10) return na === nb;
  return na.includes(nb) || nb.includes(na);
}

const uniqueJobs = [];

for (const job of incomingJobs) {
  const title = (job.json.title || '').toLowerCase().trim();
  const company = (job.json.company || '').toLowerCase().trim();
  const key = `${company}|${title}`;

  if (existingTitles.has(key)) continue;

  const isDuplicate = uniqueJobs.some(existing => {
    const ec = (existing.json.company || '').toLowerCase().trim();
    if (ec !== company) return false;
    return isSimilarTitle(existing.json.title || '', title);
  });

  if (isDuplicate) continue;

  uniqueJobs.push(job);
}

return uniqueJobs.length > 0 ? uniqueJobs : [{ json: { _empty: true } }];

const jobs = $input.all();

return jobs.filter(item => {
  if (item.json._empty) return false;

  const origTitle       = item.json.title || '';
  const origLocation    = item.json.location || '';
  const origDescription = item.json.description || '';
  const origCompany     = item.json.company || '';

  const title       = origTitle.toLowerCase();
  const location    = origLocation.toLowerCase();
  const description = origDescription.toLowerCase();

  // Catches LinkedIn's habit of injecting "Promoted" into the company or title
  const adPtn = /^\s*promoted\s*$|\b(promoted|sponsored)\b/i;
  if (adPtn.test(origTitle) || adPtn.test(origCompany)) return false;

  const platformNoticePtn = /pause before you act|be cautious|urgent demands|requests for payments|safety tip|fraud warning|job alert:|sign in to apply|create a free account|download the app|linkedin premium|easy apply only|similar jobs|people also viewed/i;
  if (platformNoticePtn.test(origTitle)) return false;
  if (platformNoticePtn.test(origDescription.substring(0, 500))) return false;

  // Block stubs — real jobs always have at least 40 words
  const wordCount = origDescription.trim().split(/\s+/).length;
  if (wordCount < 40) return false;

  // ── FIX 2: BLOCK JUNIOR & ENTRY-LEVEL ROLES ─────────────────────────────
  const juniorPtn = /\b(intern(ship)?|entry[\s\-]?level|junior\s+\w+|marketing\s+assistant|brand\s+assistant|digital\s+assistant|social\s+media\s+coordinator|marketing\s+coordinator|email\s+coordinator|content\s+coordinator|marketing\s+associate\b|for\s+(students|graduates|freshers)|recent\s+graduate|new\s+grad|0[\s\-]2\s+years|1[\s\-]2\s+years\s+experience)\b/i;
  if (juniorPtn.test(origTitle)) return false;
  if (juniorPtn.test(origDescription.substring(0, 600))) return false;

  // ── FIX 3: ENFORCE SENIORITY FOR ALL ROLES (Based on the candidate's resume) ───
  // Added 'cmo' to the global senior regex and enforced it as a strict gate
  const seniorPtn = /\b(senior|sr\b|director|vp\b|vice\s+president|head\s+of|chief|manager|lead\s+\w+|principal|executive|fractional|cmo)\b/i;
  if (!seniorPtn.test(origTitle)) return false;

  // ── EXISTING NEGATIVE KEYWORDS ───────────────────────────────────────────
  const negPtn = /\b(freshers?|for women|for men|for students|training provided|no experience required|work from home jobs for|jobs for)\b/i;
  if (negPtn.test(origTitle) || negPtn.test(origDescription)) return false;

  // ── US / REMOTE CHECK ────────────────────────────────────────────────────
  const usFullNames = /\b(united states|alabama|alaska|arizona|arkansas|california|colorado|connecticut|delaware|florida|georgia|hawaii|idaho|illinois|indiana|iowa|kansas|kentucky|louisiana|maine|maryland|massachusetts|michigan|minnesota|mississippi|missouri|montana|nebraska|nevada|new hampshire|new jersey|new mexico|new york|north carolina|north dakota|ohio|oklahoma|oregon|pennsylvania|rhode island|south carolina|south dakota|tennessee|texas|utah|vermont|virginia|washington|west virginia|wisconsin|wyoming)\b/i;
  const usAbbrs     = /\b(US|USA|U\.S\.|AL|AK|AZ|AR|CA|CO|CT|DE|FL|GA|HI|ID|IL|IN|IA|KS|KY|LA|ME|MD|MA|MI|MN|MS|MO|MT|NE|NV|NH|NJ|NM|NY|NC|ND|OH|OK|OR|PA|RI|SC|SD|TN|TX|UT|VT|VA|WA|WV|WI|WY)\b/;
  const hasUsSignal = usFullNames.test(origDescription) || usFullNames.test(origLocation) || usFullNames.test(origTitle) ||
                      usAbbrs.test(origDescription) || usAbbrs.test(origLocation) || usAbbrs.test(origTitle);

  const foreignPtn = [
    /\buk\b/i, /united kingdom|london|england|scotland|wales/i,
    /india|bangalore|delhi|mumbai/i, /canada|toronto|vancouver|ontario/i,
    /australia|sydney|melbourne/i, /europe|germany|france|spain|italy|netherlands/i,
    /philippines|pakistan|nigeria|indonesia/i,
    /mexico|brazil|argentina|chile|colombia/i,
    /UAE|dubai|saudi|singapore|malaysia/i, /south africa|kenya|ghana/i
  ];
  const hasForeign   = foreignPtn.some(p => p.test(origLocation) || p.test(origTitle) || p.test(origCompany));
  const isCleanRemote = (location.includes('remote') || location.includes('anywhere')) && hasUsSignal && !hasForeign;

  return (hasUsSignal || isCleanRemote) && !hasForeign;
});

