const results = [];

for (const item of $input.all()) {
  let cleanData = {};

  try {
    // 1. Grab the raw text from Gemini
    let rawText = item.json.candidates[0].content.parts[0].text;

    // 2. BEST CASE / NORMAL CASE: Strip out any markdown formatting LLMs love to inject
    rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

    // 3. Convert it from a dumb string into a smart Javascript object
    cleanData = JSON.parse(rawText);

  } catch (e) {
    // 4. WORST CASE: The AI completely failed to return JSON. 
    // We provide a fallback string so the workflow continues and the user knows to check it manually.
    cleanData = {
      tailored_summary: "AI formatting error. Review required.",
      cover_letter: "AI formatting error. Review required."
    };
  }

  // Pass the clean data forward
  results.push({ json: { ...item.json, ai_cleaned: cleanData } });
}

return results;

const jobs = $input.all();
const results = [];

for (const item of jobs) {
  const applyLink = item.json.apply_link || '';
  const jobLink = item.json.job_link || '';
  const source = (item.json.source || '').toLowerCase();

  // Only block known low-quality aggregators with no direct link
  const isAggregator =
    (source.includes('jobzen') || source.includes('snagajob') || source.includes('jooble')) &&
    !applyLink.includes('linkedin') &&
    !applyLink.includes('indeed');

  // Accept job if it has ANY link and isn't a bad aggregator
  const hasAnyLink = applyLink.length > 0 || jobLink.length > 0;

  if (hasAnyLink && !isAggregator) {
    results.push(item);
  }
}

if (results.length === 0) {
  return [{ json: { no_jobs: true } }];
}

return results;
